import { NextRequest } from 'next/server'
import { createClient, createServiceRoleClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const profile = await supabase
    .from('profiles')
    .select('is_platform_admin')
    .eq('id', user.id)
    .single()
  if (!profile.data?.is_platform_admin) return new Response('Forbidden', { status: 403 })

  const admin = createServiceRoleClient()

  try {
    const [
      studiosCount,
      bannedCount,
      bookingsCount,
      subsData,
      newSignupsData,
    ] = await Promise.all([
      admin.from('studios').select('id', { count: 'exact', head: true }),
      admin.from('studios').select('id', { count: 'exact', head: true }).eq('status', 'banned'),
      admin.from('bookings').select('id', { count: 'exact', head: true }),
      admin.from('subscriptions')
        .select('plan_tier, status, created_at')
        .eq('status', 'active'),
      admin.from('studios')
        .select('created_at')
        .gte('created_at', new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString())
        .order('created_at'),
    ])

    // Compute MRR from active subscriptions
    const planPrices: Record<string, number> = { solo: 29, studio: 59, pro: 99, enterprise: 199 }
    const mrr = (subsData.data ?? []).reduce((sum, s) => sum + (planPrices[s.plan_tier] ?? 0), 0)
    const arr = mrr * 12

    // Plan breakdown
    const planBreakdown = (subsData.data ?? []).reduce<Record<string, number>>((acc, s) => {
      acc[s.plan_tier] = (acc[s.plan_tier] ?? 0) + 1
      return acc
    }, {})

    // Daily signups for chart (last 30 days)
    const signupsByDay = (newSignupsData.data ?? []).reduce<Record<string, number>>((acc, s) => {
      const day = s.created_at.slice(0, 10)
      acc[day] = (acc[day] ?? 0) + 1
      return acc
    }, {})

    const signupChart = Object.entries(signupsByDay)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([date, count]) => ({ date, count }))

    return Response.json({
      totalStudios: studiosCount.count ?? 0,
      bannedStudios: bannedCount.count ?? 0,
      totalBookings: bookingsCount.count ?? 0,
      activeSubscriptions: subsData.data?.length ?? 0,
      mrr,
      arr,
      planBreakdown,
      signupChart,
    })
  } catch (err) {
    logger.error({ err }, 'admin overview failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { createClient, createServiceRoleClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'

const querySchema = z.object({
  q: z.string().optional(),
  plan: z.enum(['solo', 'studio', 'pro', 'enterprise']).optional(),
  status: z.enum(['active', 'banned', 'suspended']).optional(),
  page: z.coerce.number().int().positive().default(1),
  limit: z.coerce.number().int().min(1).max(100).default(30),
})

export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const profile = await supabase.from('profiles').select('is_platform_admin').eq('id', user.id).single()
  if (!profile.data?.is_platform_admin) return new Response('Forbidden', { status: 403 })

  const parsed = querySchema.safeParse(Object.fromEntries(req.nextUrl.searchParams))
  if (!parsed.success) return Response.json({ error: parsed.error.flatten() }, { status: 400 })

  const { q, plan, status, page, limit } = parsed.data
  const admin = createServiceRoleClient()

  try {
    let query = admin
      .from('studios')
      .select(`
        id, name, slug, status, plan_id, created_at, updated_at,
        subscriptions!inner(plan_tier, status, current_period_end),
        studio_members(count)
      `, { count: 'exact' })
      .order('created_at', { ascending: false })
      .range((page - 1) * limit, page * limit - 1)

    if (q) query = query.or(`name.ilike.%${q}%,slug.ilike.%${q}%`)
    if (status) query = query.eq('status', status)

    const { data, count, error } = await query
    if (error) throw error

    // Filter by plan in memory since it's a joined column
    const filtered = plan
      ? (data ?? []).filter((s) => {
          const sub = Array.isArray(s.subscriptions) ? s.subscriptions[0] : s.subscriptions
          return sub?.plan_tier === plan
        })
      : (data ?? [])

    return Response.json({ studios: filtered, total: count ?? 0, page, limit })
  } catch (err) {
    logger.error({ err }, 'admin studios list failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { createClient, createServiceRoleClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

interface Params { params: Promise<{ id: string }> }

export async function GET(req: NextRequest, { params }: Params) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const profile = await supabase.from('profiles').select('is_platform_admin').eq('id', user.id).single()
  if (!profile.data?.is_platform_admin) return new Response('Forbidden', { status: 403 })

  const { id } = await params
  const admin = createServiceRoleClient()

  try {
    const [studioResult, membersResult, subsResult, bookingCount] = await Promise.all([
      admin.from('studios').select('*').eq('id', id).single(),
      admin.from('studio_members').select('user_id, role, created_at, deactivated_at, profiles(email, full_name)').eq('studio_id', id),
      admin.from('subscriptions').select('*').eq('studio_id', id).order('created_at', { ascending: false }).limit(5),
      admin.from('bookings').select('id', { count: 'exact', head: true }).eq('studio_id', id),
    ])

    if (studioResult.error || !studioResult.data) {
      return Response.json({ error: 'Studio not found' }, { status: 404 })
    }

    return Response.json({
      studio: studioResult.data,
      members: membersResult.data ?? [],
      subscriptions: subsResult.data ?? [],
      bookingCount: bookingCount.count ?? 0,
    })
  } catch (err) {
    logger.error({ err, studioId: id }, 'admin studio detail failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { createClient, createServiceRoleClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

interface Params { params: Promise<{ id: string }> }

/**
 * POST /api/admin/studios/[id]/impersonate
 * Generates a 15-minute magic link for the studio owner.
 * Audit-logged. Single-use only (Supabase magic link is single-use by default).
 */
export async function POST(req: NextRequest, { params }: Params) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const profile = await supabase.from('profiles').select('is_platform_admin, email').eq('id', user.id).single()
  if (!profile.data?.is_platform_admin) return new Response('Forbidden', { status: 403 })

  const { id: studioId } = await params
  const admin = createServiceRoleClient()

  try {
    // Find the studio owner
    const ownerResult = await admin
      .from('studio_members')
      .select('user_id, profiles(email)')
      .eq('studio_id', studioId)
      .eq('role', 'owner')
      .is('deactivated_at', null)
      .limit(1)
      .single()

    if (ownerResult.error || !ownerResult.data) {
      return Response.json({ error: 'Studio owner not found' }, { status: 404 })
    }

    const ownerProfile = ownerResult.data.profiles
    const ownerEmail = Array.isArray(ownerProfile) ? ownerProfile[0]?.email : ownerProfile?.email

    if (!ownerEmail) {
      return Response.json({ error: 'Owner email not found' }, { status: 404 })
    }

    // Generate magic link (single-use, 15 min expiry)
    const { data: linkData, error: linkError } = await admin.auth.admin.generateLink({
      type: 'magiclink',
      email: ownerEmail,
      options: { expiresIn: 900 }, // 15 minutes
    })

    if (linkError || !linkData) {
      throw linkError ?? new Error('Failed to generate magic link')
    }

    await logAuditAction(
      user.id,
      'admin.impersonate',
      { type: 'studio', id: studioId },
      {
        actor_email: profile.data.email,
        target_email: ownerEmail,
        target_studio_id: studioId,
        expires_at: new Date(Date.now() + 15 * 60 * 1000).toISOString(),
      },
      null
    )

    return Response.json({
      signInUrl: linkData.properties?.action_link,
      expiresAt: new Date(Date.now() + 15 * 60 * 1000).toISOString(),
    })
  } catch (err) {
    logger.error({ err, studioId }, 'impersonate failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { createClient, createServiceRoleClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'
import { z } from 'zod'

interface Params { params: Promise<{ id: string }> }

const bodySchema = z.object({
  action: z.enum(['ban', 'unban']),
  reason: z.string().max(500).optional(),
})

export async function POST(req: NextRequest, { params }: Params) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const profile = await supabase.from('profiles').select('is_platform_admin').eq('id', user.id).single()
  if (!profile.data?.is_platform_admin) return new Response('Forbidden', { status: 403 })

  const body = bodySchema.safeParse(await req.json())
  if (!body.success) return Response.json({ error: body.error.flatten() }, { status: 400 })

  const { id: studioId } = await params
  const { action, reason } = body.data
  const admin = createServiceRoleClient()

  try {
    const newStatus = action === 'ban' ? 'banned' : 'active'
    const { error } = await admin
      .from('studios')
      .update({ status: newStatus, updated_at: new Date().toISOString() })
      .eq('id', studioId)

    if (error) throw error

    await logAuditAction(
      user.id,
      `admin.studio.${action}`,
      { type: 'studio', id: studioId },
      { reason: reason ?? null, new_status: newStatus },
      null
    )

    return Response.json({ status: newStatus })
  } catch (err) {
    logger.error({ err, studioId, action }, 'ban/unban failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { createClient, createServiceRoleClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

interface Params { params: Promise<{ id: string }> }

/**
 * GET /api/admin/studios/[id]/export
 * GDPR data export for a studio — returns all studio data as JSON.
 * Excludes raw file bytes; includes metadata and signed URLs with 1-hour TTL.
 */
export async function GET(req: NextRequest, { params }: Params) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const profile = await supabase.from('profiles').select('is_platform_admin').eq('id', user.id).single()
  if (!profile.data?.is_platform_admin) return new Response('Forbidden', { status: 403 })

  const { id: studioId } = await params
  const admin = createServiceRoleClient()

  try {
    const [
      studioResult,
      membersResult,
      bookingsResult,
      clientsResult,
      consentSubmissionsResult,
      commissionRecordsResult,
      payrollRunsResult,
      subsResult,
    ] = await Promise.all([
      admin.from('studios').select('*').eq('id', studioId).single(),
      admin.from('studio_members').select('*, profiles(email, full_name)').eq('studio_id', studioId),
      admin.from('bookings').select('*').eq('studio_id', studioId).order('created_at', { ascending: false }),
      admin.from('clients').select('id, first_name, last_name, email, phone, created_at').eq('studio_id', studioId),
      admin.from('consent_form_submissions').select('id, booking_id, signed_at, pdf_url').eq('studio_id', studioId),
      admin.from('commission_records').select('*').eq('studio_id', studioId),
      admin.from('payroll_runs').select('*').eq('studio_id', studioId),
      admin.from('subscriptions').select('*').eq('studio_id', studioId),
    ])

    if (!studioResult.data) {
      return Response.json({ error: 'Studio not found' }, { status: 404 })
    }

    await logAuditAction(
      user.id,
      'admin.gdpr_export',
      { type: 'studio', id: studioId },
      { exported_tables: ['studios', 'studio_members', 'bookings', 'clients', 'consent_form_submissions', 'commission_records', 'payroll_runs', 'subscriptions'] },
      null
    )

    const exportPayload = {
      exported_at: new Date().toISOString(),
      studio: studioResult.data,
      members: membersResult.data ?? [],
      bookings: bookingsResult.data ?? [],
      clients: clientsResult.data ?? [],
      consent_submissions: consentSubmissionsResult.data ?? [],
      commission_records: commissionRecordsResult.data ?? [],
      payroll_runs: payrollRunsResult.data ?? [],
      subscriptions: subsResult.data ?? [],
      data_map: {
        note: 'File attachments (photos, consent PDFs, tax forms) are stored in Supabase Storage. Paths are included in booking_photos.storage_path and consent_form_submissions.pdf_url. Request signed download URLs separately.',
      },
    }

    return new Response(JSON.stringify(exportPayload, null, 2), {
      headers: {
        'Content-Type': 'application/json',
        'Content-Disposition': `attachment; filename="inkos-gdpr-export-${studioId}-${Date.now()}.json"`,
      },
    })
  } catch (err) {
    logger.error({ err, studioId }, 'gdpr export failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { createClient, createServiceRoleClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'
import { z } from 'zod'

interface Params { params: Promise<{ id: string }> }

const bodySchema = z.object({
  confirm: z.string().min(1),
})

/**
 * DELETE /api/admin/studios/[id]/delete
 * Requires { confirm: "STUDIO_NAME" } in body.
 * Permanently deletes studio and all cascaded data (via FK CASCADE).
 */
export async function DELETE(req: NextRequest, { params }: Params) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const profile = await supabase.from('profiles').select('is_platform_admin').eq('id', user.id).single()
  if (!profile.data?.is_platform_admin) return new Response('Forbidden', { status: 403 })

  const body = bodySchema.safeParse(await req.json())
  if (!body.success) return Response.json({ error: body.error.flatten() }, { status: 400 })

  const { id: studioId } = await params
  const admin = createServiceRoleClient()

  try {
    const studioResult = await admin.from('studios').select('name').eq('id', studioId).single()
    if (!studioResult.data) return Response.json({ error: 'Studio not found' }, { status: 404 })

    if (body.data.confirm !== studioResult.data.name) {
      return Response.json(
        { error: `Confirmation does not match. Type "${studioResult.data.name}" exactly.` },
        { status: 422 }
      )
    }

    await logAuditAction(
      user.id,
      'admin.studio.delete',
      { type: 'studio', id: studioId },
      { studio_name: studioResult.data.name },
      null
    )

    const { error } = await admin.from('studios').delete().eq('id', studioId)
    if (error) throw error

    return Response.json({ deleted: true })
  } catch (err) {
    logger.error({ err, studioId }, 'studio delete failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { createClient, createServiceRoleClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'

const querySchema = z.object({
  actor_id: z.string().uuid().optional(),
  action: z.string().max(100).optional(),
  target_type: z.string().max(50).optional(),
  from: z.string().datetime().optional(),
  to: z.string().datetime().optional(),
  page: z.coerce.number().int().positive().default(1),
  limit: z.coerce.number().int().min(1).max(100).default(50),
})

export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const profile = await supabase.from('profiles').select('is_platform_admin').eq('id', user.id).single()
  if (!profile.data?.is_platform_admin) return new Response('Forbidden', { status: 403 })

  const parsed = querySchema.safeParse(Object.fromEntries(req.nextUrl.searchParams))
  if (!parsed.success) return Response.json({ error: parsed.error.flatten() }, { status: 400 })

  const { actor_id, action, target_type, from, to, page, limit } = parsed.data
  const admin = createServiceRoleClient()

  try {
    let query = admin
      .from('audit_log')
      .select('*, profiles!audit_log_actor_id_fkey(email, full_name)', { count: 'exact' })
      .order('created_at', { ascending: false })
      .range((page - 1) * limit, page * limit - 1)

    if (actor_id) query = query.eq('actor_id', actor_id)
    if (action) query = query.ilike('action', `%${action}%`)
    if (target_type) query = query.eq('target_type', target_type)
    if (from) query = query.gte('created_at', from)
    if (to) query = query.lte('created_at', to)

    const { data, count, error } = await query
    if (error) throw error

    return Response.json({ entries: data ?? [], total: count ?? 0, page, limit })
  } catch (err) {
