import { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'

const querySchema = z.object({
  from: z.string().datetime({ offset: true }).optional(),
  to: z.string().datetime({ offset: true }).optional(),
  group_by: z.enum(['day', 'week', 'month']).default('day'),
})

export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return new Response('Unauthorized', { status: 401 })
  if (!['owner', 'admin'].includes(auth.role)) return new Response('Forbidden', { status: 403 })

  const parsed = querySchema.safeParse(Object.fromEntries(req.nextUrl.searchParams))
  if (!parsed.success) return Response.json({ error: parsed.error.flatten() }, { status: 400 })

  const { from, to, group_by } = parsed.data
  const supabase = await createClient()

  try {
    // Fetch completed bookings with payment data
    let query = supabase
      .from('bookings')
      .select('id, scheduled_at, base_price_cents, deposit_amount_cents, tip_amount_cents, artist_id, service_id, location_id, status')
      .eq('studio_id', auth.studioId)
      .eq('status', 'completed')
      .order('scheduled_at', { ascending: true })

    if (from) query = query.gte('scheduled_at', from)
    if (to) query = query.lte('scheduled_at', to)

    const { data: bookings, error } = await query
    if (error) throw error

    // Group by period
    const grouped = (bookings ?? []).reduce<Record<string, {
      period: string
      revenue: number
      deposits: number
      tips: number
      count: number
    }>>((acc, b) => {
      const d = new Date(b.scheduled_at)
      let key: string
      if (group_by === 'month') key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`
      else if (group_by === 'week') {
        const startOfYear = new Date(d.getFullYear(), 0, 1)
        const week = Math.ceil(((d.getTime() - startOfYear.getTime()) / 86400000 + startOfYear.getDay() + 1) / 7)
        key = `${d.getFullYear()}-W${String(week).padStart(2, '0')}`
      } else key = d.toISOString().slice(0, 10)

      const rev = (b.base_price_cents ?? 0) + (b.deposit_amount_cents ?? 0)
      const tips = b.tip_amount_cents ?? 0
      const dep = b.deposit_amount_cents ?? 0
      if (!acc[key]) acc[key] = { period: key, revenue: 0, deposits: 0, tips: 0, count: 0 }
      acc[key].revenue += rev
      acc[key].deposits += dep
      acc[key].tips += tips
      acc[key].count++
      return acc
    }, {})

    const timeline = Object.values(grouped).sort((a, b) => a.period.localeCompare(b.period))

    const totalRevenue = timeline.reduce((s, r) => s + r.revenue, 0)
    const totalDeposits = timeline.reduce((s, r) => s + r.deposits, 0)
    const totalTips = timeline.reduce((s, r) => s + r.tips, 0)
    const avgSessionValue = timeline.length > 0 && (bookings?.length ?? 0) > 0
      ? Math.round(totalRevenue / (bookings?.length ?? 1))
      : 0

    return Response.json({
      timeline,
      kpis: {
        totalRevenue,
        avgSessionValue,
        depositsCollected: totalDeposits,
        tipsCollected: totalTips,
        sessionsCompleted: bookings?.length ?? 0,
      },
    })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId }, 'revenue report failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'

const querySchema = z.object({
  from: z.string().datetime({ offset: true }).optional(),
  to: z.string().datetime({ offset: true }).optional(),
})

export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return new Response('Unauthorized', { status: 401 })
  if (!['owner', 'admin'].includes(auth.role)) return new Response('Forbidden', { status: 403 })

  const parsed = querySchema.safeParse(Object.fromEntries(req.nextUrl.searchParams))
  if (!parsed.success) return Response.json({ error: parsed.error.flatten() }, { status: 400 })

  const { from, to } = parsed.data
  const supabase = await createClient()

  try {
    let bookingsQuery = supabase
      .from('bookings')
      .select('id, artist_id, base_price_cents, deposit_amount_cents, tip_amount_cents, status, scheduled_at, artists(profiles(full_name))')
      .eq('studio_id', auth.studioId)
      .in('status', ['completed', 'no_show'])

    if (from) bookingsQuery = bookingsQuery.gte('scheduled_at', from)
    if (to) bookingsQuery = bookingsQuery.lte('scheduled_at', to)

    const { data: bookings, error } = await bookingsQuery
    if (error) throw error

    // Aggregate per artist
    const artistMap = new Map<string, {
      artistId: string
      artistName: string
      revenue: number
      sessions: number
      noShows: number
      tips: number
    }>()

    for (const b of bookings ?? []) {
      if (!b.artist_id) continue
      const artistData = b.artists
      const name = Array.isArray(artistData)
        ? (Array.isArray(artistData[0]?.profiles) ? artistData[0].profiles[0]?.full_name : (artistData[0]?.profiles as { full_name?: string | null } | null)?.full_name)
        : (Array.isArray((artistData as { profiles?: unknown } | null)?.profiles)
          ? ((artistData as { profiles?: Array<{ full_name?: string | null }> } | null)?.profiles?.[0]?.full_name)
          : ((artistData as { profiles?: { full_name?: string | null } | null } | null)?.profiles?.full_name))

      const existing = artistMap.get(b.artist_id) ?? {
        artistId: b.artist_id,
        artistName: (name as string | null | undefined) ?? 'Unknown',
        revenue: 0,
        sessions: 0,
        noShows: 0,
        tips: 0,
      }

      if (b.status === 'completed') {
        existing.revenue += (b.base_price_cents ?? 0) + (b.deposit_amount_cents ?? 0)
        existing.sessions++
        existing.tips += b.tip_amount_cents ?? 0
      } else {
        existing.noShows++
      }

      artistMap.set(b.artist_id, existing)
    }

    const leaderboard = Array.from(artistMap.values())
      .map((a) => ({
        ...a,
        avgTipPct: a.revenue > 0 ? Math.round((a.tips / a.revenue) * 100) : 0,
        noShowRate: (a.sessions + a.noShows) > 0
          ? Math.round((a.noShows / (a.sessions + a.noShows)) * 100)
          : 0,
      }))
      .sort((a, b) => b.revenue - a.revenue)

    return Response.json({ leaderboard })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId }, 'artists report failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'

const querySchema = z.object({
  from: z.string().datetime({ offset: true }).optional(),
  to: z.string().datetime({ offset: true }).optional(),
})

export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return new Response('Unauthorized', { status: 401 })
  if (!['owner', 'admin'].includes(auth.role)) return new Response('Forbidden', { status: 403 })

  const parsed = querySchema.safeParse(Object.fromEntries(req.nextUrl.searchParams))
  if (!parsed.success) return Response.json({ error: parsed.error.flatten() }, { status: 400 })

  const supabase = await createClient()
  const nintyDaysAgo = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString()

  try {
    const [allClients, bookings] = await Promise.all([
      supabase.from('clients').select('id, created_at').eq('studio_id', auth.studioId),
      supabase.from('bookings')
        .select('client_id, studio_id, scheduled_at, base_price_cents, deposit_amount_cents')
        .eq('studio_id', auth.studioId)
        .eq('status', 'completed')
        .order('scheduled_at', { ascending: true }),
    ])

    if (allClients.error) throw allClients.error
    if (bookings.error) throw bookings.error

    const totalClients = allClients.data?.length ?? 0

    // Client LTV
    const clientSpend = new Map<string, number>()
    const clientLastVisit = new Map<string, string>()
    const clientFirstVisit = new Map<string, string>()

    for (const b of bookings.data ?? []) {
      if (!b.client_id) continue
      const rev = (b.base_price_cents ?? 0) + (b.deposit_amount_cents ?? 0)
      clientSpend.set(b.client_id, (clientSpend.get(b.client_id) ?? 0) + rev)
      const prev = clientLastVisit.get(b.client_id)
      if (!prev || b.scheduled_at > prev) clientLastVisit.set(b.client_id, b.scheduled_at)
      const first = clientFirstVisit.get(b.client_id)
      if (!first || b.scheduled_at < first) clientFirstVisit.set(b.client_id, b.scheduled_at)
    }

    const returningClients = Array.from(clientSpend.entries()).filter(([id]) => {
      const sessions = (bookings.data ?? []).filter((b) => b.client_id === id).length
      return sessions > 1
    }).length

    const newClients = totalClients - returningClients
    const inactiveClients = Array.from(clientLastVisit.entries())
      .filter(([, last]) => last < nintyDaysAgo).length

    const ltvValues = Array.from(clientSpend.values()).sort((a, b) => a - b)
    const avgLtv = ltvValues.length > 0 ? Math.round(ltvValues.reduce((s, v) => s + v, 0) / ltvValues.length) : 0

    return Response.json({
      totalClients,
      newClients,
      returningClients,
      inactiveClients,
      avgLtv,
      retentionRate: totalClients > 0 ? Math.round((returningClients / totalClients) * 100) : 0,
    })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId }, 'clients report failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'

const querySchema = z.object({
  from: z.string().datetime({ offset: true }).optional(),
  to: z.string().datetime({ offset: true }).optional(),
  group_by: z.enum(['day', 'week', 'month']).default('day'),
})

export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return new Response('Unauthorized', { status: 401 })
  if (!['owner', 'admin'].includes(auth.role)) return new Response('Forbidden', { status: 403 })

  const parsed = querySchema.safeParse(Object.fromEntries(req.nextUrl.searchParams))
  if (!parsed.success) return Response.json({ error: parsed.error.flatten() }, { status: 400 })

  const { from, to, group_by } = parsed.data
  const supabase = await createClient()

  try {
    let query = supabase
      .from('bookings')
      .select('id, status, scheduled_at, service_id, source, services(name)')
      .eq('studio_id', auth.studioId)
      .order('scheduled_at', { ascending: true })

    if (from) query = query.gte('scheduled_at', from)
    if (to) query = query.lte('scheduled_at', to)

    const { data: bookings, error } = await query
    if (error) throw error

    const total = bookings?.length ?? 0
    const completed = (bookings ?? []).filter((b) => b.status === 'completed').length
    const noShows = (bookings ?? []).filter((b) => b.status === 'no_show').length
    const cancelled = (bookings ?? []).filter((b) => b.status === 'cancelled').length

    // Timeline of bookings by period
    const grouped = (bookings ?? []).reduce<Record<string, number>>((acc, b) => {
      const d = new Date(b.scheduled_at)
      let key: string
      if (group_by === 'month') key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`
      else if (group_by === 'week') {
        const dow = d.getDay()
        const startOfWeek = new Date(d)
        startOfWeek.setDate(d.getDate() - dow)
        key = startOfWeek.toISOString().slice(0, 10)
      } else key = d.toISOString().slice(0, 10)
      acc[key] = (acc[key] ?? 0) + 1
      return acc
    }, {})

    const timeline = Object.entries(grouped)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([period, count]) => ({ period, count }))

    // Day of week × hour heatmap
    const heatmap: number[][] = Array.from({ length: 7 }, () => Array(24).fill(0))
    for (const b of bookings ?? []) {
      const d = new Date(b.scheduled_at)
      heatmap[d.getDay()][d.getHours()]++
    }

    // Service popularity
    const serviceCounts = (bookings ?? []).reduce<Record<string, { name: string; count: number }>>((acc, b) => {
      if (!b.service_id) return acc
      const svc = b.services
      const name = Array.isArray(svc) ? (svc[0]?.name ?? b.service_id) : ((svc as { name?: string } | null)?.name ?? b.service_id)
      if (!acc[b.service_id]) acc[b.service_id] = { name, count: 0 }
      acc[b.service_id].count++
      return acc
    }, {})

    const serviceRanking = Object.values(serviceCounts).sort((a, b) => b.count - a.count)

    return Response.json({
      kpis: {
        total,
        completed,
        noShows,
        cancelled,
        noShowRate: total > 0 ? Math.round((noShows / total) * 100) : 0,
        cancellationRate: total > 0 ? Math.round((cancelled / total) * 100) : 0,
      },
      timeline,
      heatmap,
      serviceRanking,
    })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId }, 'bookings report failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

