import { NextRequest } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'

const createSchema = z.object({
  ink_brand: z.string().min(1).max(200),
  ink_color: z.string().min(1).max(100),
  ink_product_code: z.string().max(100).optional().nullable(),
  batch_number: z.string().max(100).optional().nullable(),
  manufacture_date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional().nullable(),
  expiry_date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional().nullable(),
  reach_compliant: z.boolean().default(true),
  sds_url: z.string().url().optional().nullable(),
  notes: z.string().max(1000).optional().nullable(),
})

export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return new Response('Unauthorized', { status: 401 })

  const supabase = await createClient()
  const includeInactive = req.nextUrl.searchParams.get('include_inactive') === 'true'

  try {
    let query = supabase
      .from('studio_ink_registry')
      .select('*')
      .eq('studio_id', auth.studioId)
      .order('ink_brand', { ascending: true })

    if (!includeInactive) query = query.eq('is_active', true)

    const { data, error } = await query
    if (error) throw error

    // Flag expiring soon (within 30 days)
    const thirtyDaysFromNow = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10)
    const today = new Date().toISOString().slice(0, 10)

    const enriched = (data ?? []).map((ink) => ({
      ...ink,
      expiring_soon: ink.expiry_date != null && ink.expiry_date <= thirtyDaysFromNow && ink.expiry_date >= today,
      expired: ink.expiry_date != null && ink.expiry_date < today,
    }))

    return Response.json({ inks: enriched })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId }, 'ink registry GET failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function POST(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return new Response('Unauthorized', { status: 401 })
  if (!['owner', 'admin'].includes(auth.role)) return new Response('Forbidden', { status: 403 })

  const body = createSchema.safeParse(await req.json())
  if (!body.success) return Response.json({ error: body.error.flatten() }, { status: 400 })

  const supabase = await createClient()

  try {
