  }
}

import { NextRequest } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'

interface Params { params: Promise<{ id: string }> }

const updateSchema = z.object({
  ink_brand: z.string().min(1).max(200).optional(),
  ink_color: z.string().min(1).max(100).optional(),
  ink_product_code: z.string().max(100).optional().nullable(),
  batch_number: z.string().max(100).optional().nullable(),
  manufacture_date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional().nullable(),
  expiry_date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional().nullable(),
  reach_compliant: z.boolean().optional(),
  sds_url: z.string().url().optional().nullable(),
  notes: z.string().max(1000).optional().nullable(),
  is_active: z.boolean().optional(),
})

export async function PATCH(req: NextRequest, { params }: Params) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return new Response('Unauthorized', { status: 401 })
  if (!['owner', 'admin'].includes(auth.role)) return new Response('Forbidden', { status: 403 })

  const body = updateSchema.safeParse(await req.json())
  if (!body.success) return Response.json({ error: body.error.flatten() }, { status: 400 })

  const { id } = await params
  const supabase = await createClient()

  try {
    const updatePayload: Record<string, unknown> = { ...body.data, updated_at: new Date().toISOString() }
    if (body.data.reach_compliant === true) {
      updatePayload.reach_compliant_at = new Date().toISOString()
    }

    const { data, error } = await supabase
      .from('studio_ink_registry')
      .update(updatePayload)
      .eq('id', id)
      .eq('studio_id', auth.studioId) // RLS redundancy
      .select()
      .single()

    if (error) throw error
    return Response.json({ ink: data })
  } catch (err) {
    logger.error({ err, id }, 'ink registry update failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function DELETE(req: NextRequest, { params }: Params) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return new Response('Unauthorized', { status: 401 })
  if (!['owner', 'admin'].includes(auth.role)) return new Response('Forbidden', { status: 403 })

  const { id } = await params
  const supabase = await createClient()

  try {
    // Soft delete — mark inactive
    const { error } = await supabase
      .from('studio_ink_registry')
      .update({ is_active: false, updated_at: new Date().toISOString() })
      .eq('id', id)
      .eq('studio_id', auth.studioId)

    if (error) throw error
    return Response.json({ deleted: true })
  } catch (err) {
    logger.error({ err, id }, 'ink registry delete failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

interface Params { params: Promise<{ clientId: string }> }

/**
 * GET /api/reach/passport/[clientId]
 * Returns all REACH ink records associated with consent form submissions
 * for a specific client — the client's ink passport.
 */
export async function GET(req: NextRequest, { params }: Params) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return new Response('Unauthorized', { status: 401 })

  const { clientId } = await params
  const supabase = await createClient()

  try {
    // Get all bookings for this client in this studio
    const { data: bookings, error: bookingErr } = await supabase
      .from('bookings')
      .select('id, scheduled_at, services(name)')
      .eq('studio_id', auth.studioId)
      .eq('client_id', clientId)
      .eq('status', 'completed')
      .order('scheduled_at', { ascending: false })

    if (bookingErr) throw bookingErr

    const bookingIds = (bookings ?? []).map((b) => b.id)

    if (bookingIds.length === 0) {
      return Response.json({ passport: [], client_id: clientId })
    }

    // Get all REACH records for those bookings
    const { data: inkRecords, error: inkErr } = await supabase
      .from('reach_ink_records')
      .select('*')
      .eq('studio_id', auth.studioId)
      .in('booking_id', bookingIds)
      .order('used_at', { ascending: false })

    if (inkErr) throw inkErr

    // Join booking data to ink records
    const bookingMap = new Map((bookings ?? []).map((b) => {
      const svc = b.services
      const svcName = Array.isArray(svc) ? (svc[0]?.name ?? null) : ((svc as { name?: string } | null)?.name ?? null)
      return [b.id, { scheduled_at: b.scheduled_at, service_name: svcName }]
    }))

    const passport = (inkRecords ?? []).map((r) => ({
      ...r,
      booking: bookingMap.get(r.booking_id ?? '') ?? null,
    }))

    return Response.json({ passport, client_id: clientId })
  } catch (err) {
    logger.error({ err, clientId }, 'ink passport GET failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

interface Params { params: Promise<{ clientId: string }> }

/**
 * GET /api/reach/export/[clientId]
 * Returns the client's ink passport as a JSON compliance document.
 * EU REACH compliance export — includes all inks used across sessions.
 */
export async function GET(req: NextRequest, { params }: Params) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return new Response('Unauthorized', { status: 401 })

  const { clientId } = await params
  const supabase = await createClient()

  try {
    const [clientResult, studioResult, bookingsResult] = await Promise.all([
      supabase.from('clients').select('id, first_name, last_name, email').eq('id', clientId).eq('studio_id', auth.studioId).single(),
      supabase.from('studios').select('name, slug').eq('id', auth.studioId).single(),
      supabase.from('bookings').select('id, scheduled_at, services(name)').eq('studio_id', auth.studioId).eq('client_id', clientId).eq('status', 'completed'),
    ])

    if (!clientResult.data) return Response.json({ error: 'Client not found' }, { status: 404 })

    const bookingIds = (bookingsResult.data ?? []).map((b) => b.id)
    const { data: inkRecords } = await supabase
      .from('reach_ink_records')
      .select('*')
      .eq('studio_id', auth.studioId)
      .in('booking_id', bookingIds)
      .order('used_at', { ascending: false })

    const bookingMap = new Map((bookingsResult.data ?? []).map((b) => {
      const svc = b.services
      const svcName = Array.isArray(svc) ? (svc[0]?.name ?? null) : ((svc as { name?: string } | null)?.name ?? null)
      return [b.id, { scheduled_at: b.scheduled_at, service_name: svcName }]
    }))

    const passport = (inkRecords ?? []).map((r) => ({
      ...r,
      booking: bookingMap.get(r.booking_id ?? '') ?? null,
    }))

    const exportDoc = {
      document_type: 'EU_REACH_INK_PASSPORT',
      generated_at: new Date().toISOString(),
      studio: studioResult.data,
      client: {
        id: clientResult.data.id,
        full_name: `${clientResult.data.first_name} ${clientResult.data.last_name}`.trim(),
        email: clientResult.data.email,
      },
      ink_records: passport,
      compliance_note: 'This document is generated in accordance with EU REACH Regulation (EC) No 1907/2006 as amended by Commission Regulation (EU) 2020/2081 regarding substances in tattoo inks and permanent make-up.',
    }

    return new Response(JSON.stringify(exportDoc, null, 2), {
      headers: {
        'Content-Type': 'application/json',
        'Content-Disposition': `attachment; filename="reach-ink-passport-${clientId}.json"`,
      },
    })
  } catch (err) {
    logger.error({ err, clientId }, 'reach export failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

