const RechartsAreaChart = dynamic(() => import('./RechartsAreaChart'), {
  ssr: false,
  loading: () => <Skeleton className="h-56 w-full" />,
})
const RechartsBarChart = dynamic(() => import('./RechartsBarChart'), {
  ssr: false,
  loading: () => <Skeleton className="h-56 w-full" />,
})

type GroupBy = 'day' | 'week' | 'month'

interface RevenueData {
  timeline: Array<{ period: string; revenue: number; deposits: number; tips: number; count: number }>
  kpis: {
    totalRevenue: number
    avgSessionValue: number
    depositsCollected: number
    tipsCollected: number
    sessionsCompleted: number
  }
}

export function RevenueReportClient() {
  const [groupBy, setGroupBy] = useState<GroupBy>('day')

  const { data, isLoading, error } = useQuery<RevenueData>({
    queryKey: ['reports', 'revenue', groupBy],
    queryFn: () => fetch(`/api/reports/revenue?group_by=${groupBy}`).then((r) => r.json()),
    staleTime: 5 * 60 * 1000,
  })

  function exportCsv() {
    if (!data?.timeline) return
    const rows = [
      ['Period', 'Revenue (cents)', 'Deposits (cents)', 'Tips (cents)', 'Sessions'],
      ...data.timeline.map((r) => [r.period, r.revenue, r.deposits, r.tips, r.count]),
    ]
    const csv = rows.map((r) => r.join(',')).join('\n')
    const blob = new Blob([csv], { type: 'text/csv' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `revenue-report-${groupBy}.csv`
    a.click()
    URL.revokeObjectURL(url)
  }

  if (isLoading) return <Skeleton className="h-96 rounded-lg" />
  if (error || !data) {
    return <EmptyState icon={DollarSign} title="Failed to load revenue report" description="Try again or check your connection." />
  }

  const timelineForChart = data.timeline.map((r) => ({
    name: r.period,
    value: Math.round(r.revenue / 100),
  }))

  return (
    <div className="space-y-6">
      {/* Controls */}
      <div className="flex items-center justify-between gap-4">
        <ToggleGroup
          type="single"
          value={groupBy}
          onValueChange={(v) => { if (v) setGroupBy(v as GroupBy) }}
          className="border border-border rounded-md p-0.5"
        >
          <ToggleGroupItem value="day" size="sm">Daily</ToggleGroupItem>
          <ToggleGroupItem value="week" size="sm">Weekly</ToggleGroupItem>
          <ToggleGroupItem value="month" size="sm">Monthly</ToggleGroupItem>
        </ToggleGroup>
        <Button size="sm" variant="outline" onClick={exportCsv}>
          <Download className="mr-2 h-4 w-4" />
          Export CSV
        </Button>
      </div>

      {/* KPIs */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-5">
        <KpiCard label="Total Revenue" value={formatCurrency(data.kpis.totalRevenue)} subtext="all sessions" icon={DollarSign} trend="up" index={0} />
        <KpiCard label="Avg Session" value={formatCurrency(data.kpis.avgSessionValue)} subtext="per completed booking" icon={TrendingUp} index={1} />
        <KpiCard label="Deposits" value={formatCurrency(data.kpis.depositsCollected)} subtext="collected" icon={DollarSign} index={2} />
        <KpiCard label="Tips" value={formatCurrency(data.kpis.tipsCollected)} subtext="collected" icon={DollarSign} trend="up" index={3} />
        <KpiCard label="Sessions" value={data.kpis.sessionsCompleted} subtext="completed" icon={TrendingUp} index={4} />
      </div>

      {/* Revenue timeline */}
      <Card className="border-border/50 shadow-[var(--shadow-card)]">
        <CardHeader>
          <CardTitle className="text-sm font-medium">Revenue Over Time</CardTitle>
        </CardHeader>
        <CardContent>
          {timelineForChart.length === 0 ? (
            <EmptyState icon={DollarSign} title="No revenue data" description="Completed sessions will appear here." />
          ) : (
            <RechartsAreaChart
              data={timelineForChart}
              dataKey="value"
              label="Revenue ($)"
              formatValue={(v) => `$${v}`}
            />
          )}
        </CardContent>
      </Card>

      {/* By service */}
      <Card className="border-border/50 shadow-[var(--shadow-card)]">
        <CardHeader>
          <CardTitle className="text-sm font-medium">Revenue by Period</CardTitle>
        </CardHeader>
        <CardContent>
          {timelineForChart.length === 0 ? (
            <EmptyState icon={TrendingUp} title="No data" description="Revenue breakdown will appear here." />
          ) : (
            <RechartsBarChart
              data={timelineForChart}
              dataKey="value"
              label="Revenue ($)"
              formatValue={(v) => `$${v}`}
            />
          )}
        </CardContent>
      </Card>
    </div>
  )
}

