const RechartsBarChart = dynamic(() => import('./RechartsBarChart'), {
  ssr: false,
  loading: () => <Skeleton className="h-56 w-full" />,
})

interface BookingKpis {
  total: number
  completed: number
  noShows: number
  cancelled: number
  noShowRate: number
  cancellationRate: number
}

interface BookingsData {
  kpis: BookingKpis
  timeline: Array<{ period: string; count: number }>
  heatmap: number[][] // [7][24]
  serviceRanking: Array<{ name: string; count: number }>
}

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']

function HeatmapCell({ value, max }: { value: number; max: number }) {
  const intensity = max > 0 ? value / max : 0
  const opacity = Math.round(intensity * 100)
  return (
    <div
      title={`${value} bookings`}
      className="h-3 w-3 rounded-sm"
      style={{ backgroundColor: `hsl(var(--color-primary) / ${Math.max(opacity, 4)}%)` }}
    />
  )
}

export function BookingsReportClient() {
  const { data, isLoading, error } = useQuery<BookingsData>({
    queryKey: ['reports', 'bookings'],
    queryFn: () => fetch('/api/reports/bookings').then((r) => r.json()),
    staleTime: 5 * 60 * 1000,
  })

  if (isLoading) return <Skeleton className="h-96 rounded-lg" />
  if (error || !data) {
    return (
      <EmptyState
        icon={CalendarDays}
        title="Failed to load booking report"
        description="Try again or check your connection."
      />
    )
  }

  const timelineForChart = data.timeline.map((r) => ({ name: r.period, value: r.count }))
  const maxHeat = Math.max(...data.heatmap.flat())

  return (
    <div className="space-y-6">
      {/* KPIs */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        <KpiCard label="Total Bookings" value={data.kpis.total} subtext="in period" icon={CalendarDays} index={0} />
        <KpiCard label="Completed" value={data.kpis.completed} subtext="sessions completed" icon={CalendarDays} trend="up" index={1} />
        <KpiCard label="No-Shows" value={data.kpis.noShows} subtext={`${data.kpis.noShowRate}% no-show rate`} icon={TrendingDown} invertTrend trend={data.kpis.noShows > 0 ? 'up' : 'neutral'} index={2} />
        <KpiCard label="Cancelled" value={data.kpis.cancelled} subtext={`${data.kpis.cancellationRate}% cancellation rate`} icon={TrendingDown} invertTrend trend={data.kpis.cancelled > 0 ? 'up' : 'neutral'} index={3} />
        <KpiCard label="No-Show Rate" value={`${data.kpis.noShowRate}%`} subtext="of total bookings" icon={TrendingDown} invertTrend trend={data.kpis.noShowRate > 10 ? 'up' : 'neutral'} index={4} />
        <KpiCard label="Cancellation Rate" value={`${data.kpis.cancellationRate}%`} subtext="of total bookings" icon={TrendingDown} invertTrend trend={data.kpis.cancellationRate > 15 ? 'up' : 'neutral'} index={5} />
      </div>

      {/* Bookings timeline */}
      <Card className="border-border/50 shadow-[var(--shadow-card)]">
        <CardHeader>
          <CardTitle className="text-sm font-medium">Bookings Over Time</CardTitle>
        </CardHeader>
        <CardContent>
          {timelineForChart.length === 0 ? (
            <EmptyState icon={CalendarDays} title="No booking data" description="Bookings will appear here once created." />
          ) : (
            <RechartsBarChart
              data={timelineForChart}
              dataKey="value"
              label="Bookings"
              formatValue={(v) => `${v}`}
            />
          )}
        </CardContent>
      </Card>

      {/* Heatmap */}
      <Card className="border-border/50 shadow-[var(--shadow-card)]">
        <CardHeader>
          <CardTitle className="text-sm font-medium">Booking Heatmap — Day × Hour</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <div className="inline-flex flex-col gap-1 min-w-max">
              <div className="flex gap-1 pl-8">
                {Array.from({ length: 24 }, (_, h) => (
                  <div key={h} className="w-3 text-center text-[9px] text-muted-foreground leading-none">
                    {h % 6 === 0 ? `${h}` : ''}
                  </div>
                ))}
              </div>
              {data.heatmap.map((row, dayIndex) => (
                <div key={dayIndex} className="flex items-center gap-1">
                  <span className="w-7 text-right text-[10px] text-muted-foreground shrink-0">
                    {DAYS[dayIndex]}
                  </span>
                  {row.map((val, h) => (
                    <HeatmapCell key={h} value={val} max={maxHeat} />
                  ))}
                </div>
              ))}
            </div>
          </div>
          <p className="mt-3 text-xs text-muted-foreground">Darker = more bookings at that day/hour.</p>
        </CardContent>
      </Card>

      {/* Service ranking */}
      {data.serviceRanking.length > 0 && (
        <Card className="border-border/50 shadow-[var(--shadow-card)]">
          <CardHeader>
            <CardTitle className="text-sm font-medium">Services by Popularity</CardTitle>
          </CardHeader>
          <CardContent className="p-0">
            <div className="divide-y divide-border/50">
              {data.serviceRanking.slice(0, 10).map((svc, i) => (
                <div key={svc.name} className="flex items-center gap-4 px-6 py-3">
                  <span className="w-5 text-center text-sm font-bold text-muted-foreground tabular-nums">{i + 1}</span>
                  <span className="flex-1 text-sm font-medium truncate">{svc.name}</span>
                  <Badge variant="secondary">{svc.count} bookings</Badge>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  )
}

