'use client'

import { useState } from 'react'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { Copy, ExternalLink, AlertTriangle } from 'lucide-react'
import { toast } from 'sonner'

interface ImpersonateModalProps {
  studio: { id: string; name: string } | null
  onClose: () => void
}

interface ImpersonateResult {
  signInUrl: string
  expiresAt: string
}

export function ImpersonateModal({ studio, onClose }: ImpersonateModalProps) {
  const [isLoading, setIsLoading] = useState(false)
  const [result, setResult] = useState<ImpersonateResult | null>(null)

  async function handleImpersonate() {
    if (!studio) return
    setIsLoading(true)
    try {
      const res = await fetch(`/api/admin/studios/${studio.id}/impersonate`, { method: 'POST' })
      if (!res.ok) {
        const body = await res.json() as { error?: string }
        throw new Error(body.error ?? 'Failed to generate impersonation link')
      }
      const data = await res.json() as ImpersonateResult
      setResult(data)
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to impersonate')
    } finally {
      setIsLoading(false)
    }
  }

  function copyLink() {
    if (!result) return
    void navigator.clipboard.writeText(result.signInUrl)
    toast.success('Link copied')
  }

  function handleClose() {
    setResult(null)
    onClose()
  }

  const expiresIn = result
    ? Math.round((new Date(result.expiresAt).getTime() - Date.now()) / 60_000)
    : 0

  return (
    <Dialog open={!!studio} onOpenChange={(open) => { if (!open) handleClose() }}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Impersonate Studio</DialogTitle>
          <DialogDescription>
            Generate a one-time sign-in link for <strong>{studio?.name}</strong>. This is audit-logged and expires in 15 minutes.
          </DialogDescription>
        </DialogHeader>

        {!result ? (
          <>
            <Alert>
              <AlertTriangle className="h-4 w-4" />
              <AlertDescription className="text-xs">
                All actions performed during impersonation are audit-logged under your admin account. Only use for support purposes.
              </AlertDescription>
            </Alert>
            <DialogFooter>
              <Button variant="outline" onClick={handleClose}>Cancel</Button>
              <Button onClick={handleImpersonate} disabled={isLoading} variant="destructive">
                {isLoading ? 'Generating...' : 'Generate Link'}
              </Button>
            </DialogFooter>
          </>
        ) : (
          <>
            <Alert>
              <AlertDescription className="text-xs">
                Link expires in ~{expiresIn} minutes. Single-use only.
              </AlertDescription>
            </Alert>
            <div className="rounded-md bg-muted p-3 font-mono text-xs break-all">
              {result.signInUrl}
            </div>
            <DialogFooter className="gap-2">
              <Button variant="outline" size="sm" onClick={copyLink}>
                <Copy className="mr-2 h-3 w-3" />
                Copy link
              </Button>
              <Button
                size="sm"
                onClick={() => window.open(result.signInUrl, '_blank')}
              >
                <ExternalLink className="mr-2 h-3 w-3" />
                Open
              </Button>
              <Button variant="ghost" size="sm" onClick={handleClose}>Done</Button>
            </DialogFooter>
          </>
        )}
      </DialogContent>
    </Dialog>
  )
}

