import { useState } from 'react'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import { Label } from '@/components/ui/label'
import { toast } from 'sonner'

interface BanModalProps {
  studio: { id: string; name: string; status: string } | null
  onClose: () => void
  onSuccess: () => void
}

export function BanModal({ studio, onClose, onSuccess }: BanModalProps) {
  const [reason, setReason] = useState('')
  const [isLoading, setIsLoading] = useState(false)

  const isBanning = studio?.status !== 'banned'

  async function handleSubmit() {
    if (!studio) return
    setIsLoading(true)
    try {
      const res = await fetch(`/api/admin/studios/${studio.id}/ban`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: isBanning ? 'ban' : 'unban', reason: reason || undefined }),
      })
      if (!res.ok) {
        const body = await res.json() as { error?: string }
        throw new Error(body.error ?? 'Operation failed')
      }
      toast.success(isBanning ? `${studio.name} has been banned` : `${studio.name} has been unbanned`)
      onSuccess()
      handleClose()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed')
    } finally {
      setIsLoading(false)
    }
  }

  function handleClose() {
    setReason('')
    onClose()
  }

  return (
    <Dialog open={!!studio} onOpenChange={(open) => { if (!open) handleClose() }}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>{isBanning ? 'Ban Studio' : 'Unban Studio'}</DialogTitle>
          <DialogDescription>
            {isBanning
              ? `Banning ${studio?.name} will prevent all users from accessing it.`
              : `Restoring access for ${studio?.name}.`}
          </DialogDescription>
        </DialogHeader>

        {isBanning && (
          <div className="space-y-2">
            <Label htmlFor="reason">Reason (optional)</Label>
            <Textarea
              id="reason"
              placeholder="Reason for banning..."
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              rows={3}
            />
          </div>
        )}

        <DialogFooter>
          <Button variant="outline" onClick={handleClose}>Cancel</Button>
          <Button
            variant={isBanning ? 'destructive' : 'default'}
            onClick={handleSubmit}
            disabled={isLoading}
          >
            {isLoading ? 'Processing...' : isBanning ? 'Ban Studio' : 'Unban Studio'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

