import { AlertTriangle } from 'lucide-react'
import { toast } from 'sonner'

interface DeleteStudioModalProps {
  studio: { id: string; name: string } | null
  onClose: () => void
  onSuccess: () => void
}

export function DeleteStudioModal({ studio, onClose, onSuccess }: DeleteStudioModalProps) {
  const [confirm, setConfirm] = useState('')
  const [isLoading, setIsLoading] = useState(false)

  const matches = confirm === studio?.name

  async function handleDelete() {
    if (!studio || !matches) return
    setIsLoading(true)
    try {
      const res = await fetch(`/api/admin/studios/${studio.id}/delete`, {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ confirm: studio.name }),
      })
      if (!res.ok) {
        const body = await res.json() as { error?: string }
        throw new Error(body.error ?? 'Delete failed')
      }
      toast.success(`${studio.name} has been permanently deleted`)
      onSuccess()
      handleClose()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Delete failed')
    } finally {
      setIsLoading(false)
    }
  }

  function handleClose() {
    setConfirm('')
    onClose()
  }

  return (
    <Dialog open={!!studio} onOpenChange={(open) => { if (!open) handleClose() }}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Delete Studio Permanently</DialogTitle>
          <DialogDescription>
            This will permanently delete <strong>{studio?.name}</strong> and all associated data. This cannot be undone.
          </DialogDescription>
        </DialogHeader>

        <Alert variant="destructive">
          <AlertTriangle className="h-4 w-4" />
          <AlertDescription className="text-xs">
            All bookings, clients, consent forms, artists, payments, and commission records will be permanently erased.
          </AlertDescription>
        </Alert>

        <div className="space-y-2">
          <Label htmlFor="confirm-name">
            Type <strong>{studio?.name}</strong> to confirm
          </Label>
          <Input
            id="confirm-name"
            placeholder={studio?.name}
            value={confirm}
            onChange={(e) => setConfirm(e.target.value)}
            className={matches ? 'border-destructive' : ''}
          />
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={handleClose}>Cancel</Button>
          <Button
            variant="destructive"
            onClick={handleDelete}
            disabled={!matches || isLoading}
          >
            {isLoading ? 'Deleting...' : 'Delete Forever'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

