import { StudiosList } from '@/components/admin/studios/StudiosList'
import { ImpersonateModal } from '@/components/admin/studios/ImpersonateModal'
import { BanModal } from '@/components/admin/studios/BanModal'
import { DeleteStudioModal } from '@/components/admin/studios/DeleteStudioModal'

interface StudioRow {
  id: string
  name: string
  slug: string
  status: string
  created_at: string
  subscriptions?: Array<{ plan_tier: string; status: string }>
}

export function StudiosPageClient() {
  const queryClient = useQueryClient()
  const [impersonating, setImpersonating] = useState<StudioRow | null>(null)
  const [banning, setBanning] = useState<StudioRow | null>(null)
  const [deleting, setDeleting] = useState<StudioRow | null>(null)

  const handleGdprExport = useCallback(async (studio: StudioRow) => {
    try {
      const res = await fetch(`/api/admin/studios/${studio.id}/export`)
      if (!res.ok) throw new Error('Export failed')
      const blob = await res.blob()
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `gdpr-export-${studio.slug}-${Date.now()}.json`
      a.click()
      URL.revokeObjectURL(url)
      toast.success('GDPR export downloaded')
    } catch {
      toast.error('GDPR export failed')
    }
  }, [])

  const invalidateStudios = useCallback(() => {
    void queryClient.invalidateQueries({ queryKey: ['admin', 'studios'] })
  }, [queryClient])

  return (
    <div className="p-6 max-w-7xl space-y-6">
      <div>
        <h1 className="text-2xl font-semibold tracking-tight">Studios</h1>
        <p className="mt-1 text-sm text-muted-foreground">
          Manage all studios on the platform.
        </p>
      </div>

      <StudiosList
        onImpersonate={setImpersonating}
        onBan={setBanning}
        onGdprExport={handleGdprExport}
        onDelete={setDeleting}
      />

      <ImpersonateModal
        studio={impersonating}
        onClose={() => setImpersonating(null)}
      />

      <BanModal
        studio={banning}
        onClose={() => setBanning(null)}
        onSuccess={invalidateStudios}
      />

      <DeleteStudioModal
        studio={deleting}
        onClose={() => setDeleting(null)}
        onSuccess={invalidateStudios}
      />
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { Flag, Plus, Trash2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Switch } from '@/components/ui/switch'
import { Badge } from '@/components/ui/badge'
import { Skeleton } from '@/components/ui/skeleton'
import { EmptyState } from '@/components/shared/EmptyState'
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog'
import { toast } from 'sonner'

interface FeatureFlag {
  id: string
  flag_key: string
  studio_id: string | null
  enabled: boolean
  note: string | null
  expires_at: string | null
}

interface FlagsResponse {
  flags: FeatureFlag[]
}

export function FeatureFlagManager() {
  const queryClient = useQueryClient()
  const [newKey, setNewKey] = useState('')
  const [newEnabled, setNewEnabled] = useState(true)
  const [newNote, setNewNote] = useState('')
  const [dialogOpen, setDialogOpen] = useState(false)

  const { data, isLoading } = useQuery<FlagsResponse>({
    queryKey: ['admin', 'feature-flags'],
    queryFn: () => fetch('/api/admin/system/feature-flags').then((r) => r.json()),
    staleTime: 60_000,
  })

  const createMutation = useMutation({
    mutationFn: (body: { flag_key: string; enabled: boolean; note: string }) =>
      fetch('/api/admin/system/feature-flags', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      }).then((r) => { if (!r.ok) throw new Error('Failed to create flag'); return r.json() }),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['admin', 'feature-flags'] })
      toast.success('Feature flag created')
      setDialogOpen(false)
      setNewKey('')
      setNewNote('')
    },
    onError: () => toast.error('Failed to create flag'),
  })

  const toggleMutation = useMutation({
    mutationFn: ({ id, enabled }: { id: string; enabled: boolean }) =>
      fetch(`/api/admin/system/feature-flags/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ enabled }),
      }).then((r) => { if (!r.ok) throw new Error('Failed'); return r.json() }),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['admin', 'feature-flags'] })
    },
    onError: () => toast.error('Failed to update flag'),
  })

  const deleteMutation = useMutation({
    mutationFn: (id: string) =>
      fetch(`/api/admin/system/feature-flags/${id}`, { method: 'DELETE' })
        .then((r) => { if (!r.ok) throw new Error('Failed'); return r }),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['admin', 'feature-flags'] })
      toast.success('Flag deleted')
    },
    onError: () => toast.error('Failed to delete flag'),
  })

  if (isLoading) return <Skeleton className="h-48" />

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <p className="text-sm text-muted-foreground">{data?.flags.length ?? 0} flags</p>
        <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
          <DialogTrigger asChild>
            <Button size="sm">
              <Plus className="mr-2 h-4 w-4" />
              New Flag
            </Button>
          </DialogTrigger>
          <DialogContent className="sm:max-w-sm">
            <DialogHeader>
              <DialogTitle>Create Feature Flag</DialogTitle>
            </DialogHeader>
            <div className="space-y-4">
              <div className="space-y-2">
                <Label>Flag key</Label>
                <Input
                  placeholder="e.g. ai_design, multi_location"
                  value={newKey}
                  onChange={(e) => setNewKey(e.target.value)}
                  className="font-mono"
                />
              </div>
              <div className="space-y-2">
                <Label>Note (optional)</Label>
                <Input
                  placeholder="What does this flag control?"
                  value={newNote}
                  onChange={(e) => setNewNote(e.target.value)}
                />
              </div>
              <div className="flex items-center gap-2">
                <Switch checked={newEnabled} onCheckedChange={setNewEnabled} id="new-enabled" />
                <Label htmlFor="new-enabled">Enabled by default</Label>
              </div>
            </div>
            <DialogFooter>
              <Button variant="outline" onClick={() => setDialogOpen(false)}>Cancel</Button>
              <Button
                disabled={!newKey.trim() || createMutation.isPending}
                onClick={() => createMutation.mutate({ flag_key: newKey.trim(), enabled: newEnabled, note: newNote })}
              >
                {createMutation.isPending ? 'Creating...' : 'Create'}
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </div>

      {!data?.flags.length ? (
        <EmptyState icon={Flag} title="No feature flags" description="Create flags to enable/disable features per studio." />
      ) : (
        <div className="rounded-lg border border-border/50 divide-y divide-border/50">
          {data.flags.map((flag) => (
            <div key={flag.id} className="flex items-center gap-4 px-4 py-3">
              <Switch
                checked={flag.enabled}
                onCheckedChange={(enabled) => toggleMutation.mutate({ id: flag.id, enabled })}
                disabled={toggleMutation.isPending}
              />
              <div className="flex-1 min-w-0">
                <p className="text-sm font-mono font-medium">{flag.flag_key}</p>
                {flag.note && <p className="text-xs text-muted-foreground truncate">{flag.note}</p>}
              </div>
              {flag.studio_id && (
                <Badge variant="outline" className="text-xs shrink-0">studio-scoped</Badge>
              )}
              {flag.expires_at && (
                <Badge variant="secondary" className="text-xs shrink-0">
                  exp {new Date(flag.expires_at).toLocaleDateString()}
                </Badge>
              )}
              <Button
                variant="ghost"
                size="icon"
                className="h-8 w-8 text-muted-foreground hover:text-destructive"
                onClick={() => deleteMutation.mutate(flag.id)}
                disabled={deleteMutation.isPending}
              >
                <Trash2 className="h-4 w-4" />
              </Button>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

