'use client'

import { useState } from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { Droplets, Plus, AlertTriangle, ExternalLink } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Skeleton } from '@/components/ui/skeleton'
import { EmptyState } from '@/components/shared/EmptyState'
import { InkForm } from './InkForm'
import { toast } from 'sonner'

interface InkRecord {
  id: string
  ink_brand: string
  ink_color: string
  ink_product_code: string | null
  batch_number: string | null
  expiry_date: string | null
  reach_compliant: boolean
  sds_url: string | null
  is_active: boolean
  expiring_soon: boolean
  expired: boolean
}

interface RegistryResponse {
  inks: InkRecord[]
}

export function InkRegistryTable() {
  const queryClient = useQueryClient()
  const [formOpen, setFormOpen] = useState(false)

  const { data, isLoading, error } = useQuery<RegistryResponse>({
    queryKey: ['reach', 'registry'],
    queryFn: () => fetch('/api/reach/registry').then((r) => r.json()),
    staleTime: 2 * 60 * 1000,
  })

  async function handleDeactivate(id: string) {
    const res = await fetch(`/api/reach/registry/${id}`, {
      method: 'DELETE',
    })
    if (!res.ok) {
      toast.error('Failed to remove ink')
      return
    }
    toast.success('Ink removed from registry')
    void queryClient.invalidateQueries({ queryKey: ['reach', 'registry'] })
  }

  if (isLoading) return <Skeleton className="h-64" />
  if (error || !data) {
    return <EmptyState icon={Droplets} title="Failed to load ink registry" description="Try refreshing." />
  }

  const alertCount = data.inks.filter((i) => i.expired || i.expiring_soon).length

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <p className="text-sm text-muted-foreground">{data.inks.length} inks</p>
          {alertCount > 0 && (
            <Badge variant="destructive" className="gap-1">
              <AlertTriangle className="h-3 w-3" />
              {alertCount} expiring/expired
            </Badge>
          )}
        </div>
        <Button size="sm" onClick={() => setFormOpen(true)}>
          <Plus className="mr-2 h-4 w-4" />
          Add Ink
        </Button>
      </div>

      {data.inks.length === 0 ? (
        <EmptyState
          icon={Droplets}
          title="No inks in registry"
          description="Add the inks your studio uses to generate EU REACH-compliant client passports."
        />
      ) : (
        <div className="rounded-lg border border-border/50 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-muted/40 border-b border-border/50">
                <tr>
                  <th className="px-4 py-3 text-left font-medium text-muted-foreground">Brand / Color</th>
                  <th className="px-4 py-3 text-left font-medium text-muted-foreground">Product / Batch</th>
                  <th className="px-4 py-3 text-left font-medium text-muted-foreground">Expiry</th>
                  <th className="px-4 py-3 text-left font-medium text-muted-foreground">Status</th>
                  <th className="px-4 py-3 text-right font-medium text-muted-foreground">SDS</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border/50">
                {data.inks.map((ink) => (
                  <tr
                    key={ink.id}
                    className={[
                      'hover:bg-muted/20 transition-colors',
                      ink.expired ? 'bg-destructive/5' : ink.expiring_soon ? 'bg-amber-500/5' : '',
                    ].join(' ')}
                  >
                    <td className="px-4 py-3">
                      <p className="font-medium">{ink.ink_brand}</p>
                      <p className="text-xs text-muted-foreground">{ink.ink_color}</p>
                    </td>
                    <td className="px-4 py-3 text-xs text-muted-foreground font-mono">
                      {ink.ink_product_code ?? '—'}
                      {ink.batch_number && <span className="block">{ink.batch_number}</span>}
                    </td>
                    <td className="px-4 py-3 text-xs tabular-nums">
                      {ink.expiry_date
                        ? (
                          <span className={ink.expired ? 'text-destructive font-medium' : ink.expiring_soon ? 'text-amber-600 font-medium' : 'text-muted-foreground'}>
                            {ink.expiry_date}
                            {ink.expired && ' (expired)'}
                            {ink.expiring_soon && !ink.expired && ' (soon)'}
                          </span>
                        )
                        : <span className="text-muted-foreground">No expiry</span>
                      }
                    </td>
                    <td className="px-4 py-3">
                      <div className="flex gap-1 flex-wrap">
                        {ink.reach_compliant && (
                          <Badge variant="secondary" className="text-xs">REACH</Badge>
                        )}
                        {!ink.reach_compliant && (
                          <Badge variant="destructive" className="text-xs">Non-compliant</Badge>
                        )}
                      </div>
                    </td>
                    <td className="px-4 py-3 text-right">
                      <div className="flex items-center justify-end gap-2">
                        {ink.sds_url && (
                          <Button variant="ghost" size="icon" className="h-7 w-7" asChild>
                            <a href={ink.sds_url} target="_blank" rel="noopener noreferrer">
                              <ExternalLink className="h-3 w-3" />
                            </a>
                          </Button>
                        )}
                        <Button
                          variant="ghost"
                          size="sm"
                          className="text-xs text-muted-foreground hover:text-destructive"
                          onClick={() => handleDeactivate(ink.id)}
                        >
                          Remove
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      <InkForm
        open={formOpen}
        onClose={() => setFormOpen(false)}
        onSuccess={() => void queryClient.invalidateQueries({ queryKey: ['reach', 'registry'] })}
      />
    </div>
  )
}

import type { Metadata } from 'next'
