import { NextRequest } from 'next/server'
import { createClient, createServiceRoleClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

interface Params { params: Promise<{ id: string }> }

/**
 * POST /api/admin/studios/[id]/impersonate
 * Generates a 15-minute magic link for the studio owner.
 * Audit-logged. Single-use only (Supabase magic link is single-use by default).
 */
export async function POST(req: NextRequest, { params }: Params) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const profile = await supabase.from('profiles').select('is_platform_admin').eq('id', user.id).single()
  if (!profile.data?.is_platform_admin) return new Response('Forbidden', { status: 403 })

  const { id: studioId } = await params
  const admin = createServiceRoleClient()

  try {
    // Find the studio owner via studio_members + auth.users (via admin API)
    const ownerResult = await admin
      .from('studio_members')
      .select('user_id')
      .eq('studio_id', studioId)
      .eq('role', 'owner')
      .is('deactivated_at', null)
      .limit(1)
      .single()

    if (ownerResult.error || !ownerResult.data) {
      return Response.json({ error: 'Studio owner not found' }, { status: 404 })
    }

    // Get owner email from auth admin API
    const { data: ownerAuthUser, error: authUserError } = await admin.auth.admin.getUserById(ownerResult.data.user_id)
    if (authUserError || !ownerAuthUser?.user?.email) {
      return Response.json({ error: 'Owner email not found' }, { status: 404 })
    }

    const ownerEmail = ownerAuthUser.user.email

    // Generate magic link (single-use — Supabase default)
    const { data: linkData, error: linkError } = await admin.auth.admin.generateLink({
      type: 'magiclink',
      email: ownerEmail,
    })

    if (linkError || !linkData) {
      throw linkError ?? new Error('Failed to generate magic link')
    }

    const expiresAt = new Date(Date.now() + 15 * 60 * 1000).toISOString()

    await logAuditAction(
      user.id,
      'admin.impersonate',
      { type: 'studio', id: studioId },
      {
        target_email: ownerEmail,
        target_studio_id: studioId,
        expires_at: expiresAt,
      },
      null
    )

    return Response.json({
      signInUrl: linkData.properties?.action_link,
      expiresAt,
    })
  } catch (err) {
    logger.error({ err, studioId }, 'impersonate failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

